function wssSeries(refs, delta) {
  return refs.map(function (_, t) {
    var s = {};
    for (var i = Math.max(0, t - delta + 1); i <= t; i++) s[refs[i]] = true;
    return Object.keys(s).length;
  });
}
function mustSuspend(wssList, frames) {
  return wssList.reduce(function (a, b) { return a + b; }, 0) > frames;
}
